type ChecklistDraftItem={id:string;text:string;done:boolean};const parseChecklistDraft=(value:string):ChecklistDraftItem[]=>value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>({id:crypto.randomUUID(),text:line.replace(/^\[[ xX]\]\s*/,""),done:/^\[x\]/i.test(line)}));type Task = { id: string; roundId?: string; title: string; approvalStatus?: "pending" | "approved" | "changes_requested"; createdByUserId?: string; approvedBy?: string; approvedAt?: string; description: string; billingStatus?: "Not billed" | "Billed"; billingOwner?: "Me" | "Senior"; billingAmount?: number; amountPaid?: number; paymentStatus?: "Unpaid" | "Partially paid" | "Paid"; filingAckDocument?: {name:string;dataUrl:string;size:number}; status: Status; priority: Priority; category: string; due: string; project: string; client: string; juniors: string[]; juniorUserIds?: string[]; preparerUserId?: string; financialYear?: string; assessmentYear?: string; taxYear?: string; taskType?: string; preparer?: string; reviewer?: string; notes?: string; matterName?: string; matterType?: string; applicableAct?: string; documentLinks?: string; uploadedDocuments?: {name:string;dataUrl:string;size:number}[]; statutoryDue?: string; orderDate?: string; noticeDue?: string; noticeDin?:string; noticeSection?:string; noticeOfficer?:string; hearingDate?:string; limitationDate?:string; statutorySource?:string; statutorySourceVerifiedAt?:string; internalDue?: string; checklist?: {text:string;done:boolean}[]; reviewComments?: string; activity?: {at:string;message:string;actor?:string}[]; lastClientFollowUp?: string; nextClientFollowUp?: string; lastFollowUpOutcome?: string; filedDate?: string; filingAck?: string; lastProgressUpdate?: string; completedAt?: string; deletedAt?: string; reworkCount?: number };
const seed: Task[] = [];
function safeStorageSet(key:string,value:string){try{localStorage.setItem(key,value);return true}catch(error){if(typeof window!=="undefined"){try{window.dispatchEvent(new CustomEvent("officeflow-storage-quota-error",{detail:{key,reason:error instanceof Error?error.name:"storage-error"}}))}catch{}}return false}}
const statuses: Status[] = ["To Do","In Progress","Partially replied","Fully replied","Waiting for client","Waiting for documents","Ready for review","Under Review","Rework required","Approved","Filed / completed","Closed","On hold"];
