const indiaDate = (offsetDays=0) => { const parts=new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Kolkata",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date(Date.now()+offsetDays*86400000));const get=(type:string)=>parts.find(p=>p.type===type)?.value||"00";return `${get("year")}-${get("month")}-${get("day")}`; };
const localDate = () => indiaDate();
const indiaDateOffset = (days:number) => indiaDate(days);
const isValidISODate = (value:string) => { if(!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false; const [y,m,d]=value.split("-").map(Number); const date=new Date(y,m-1,d); return date.getFullYear()===y && date.getMonth()===m-1 && date.getDate()===d; };
