 const compOffDayType=(value:string)=>compOffQualifyingDayType(value,compOffHolidays);
 function addCompOffEarned(){if(compOffDate>localDate()){showToast("Record comp-off only after the non-working day has occurred");return}const kind=compOffDayType(compOffDate);if(!kind){showToast("Selected date is not a configured non-working day");return}if(kind.startsWith("Reference holiday")&&!window.confirm("This date is a central, restricted or provisional reference, not automatically a holiday for your office. Confirm that your firm was closed and record comp-off?"))return;if(compOffEntries.some(e=>e.type==="earned"&&e.date===compOffDate)){showToast("Comp-off already recorded for this date");return}setCompOffEntries(old=>normalizeCompOffEntries([...old,{id:crypto.randomUUID(),type:"earned",date:compOffDate,expiresAt:compOffExpiry(compOffDate),notes:compOffNote.trim()||kind}]));setCompOffNote("");showToast("1 comp-off day earned · valid through "+compOffExpiry(compOffDate));}
 function addCompOffUsed(){if(compOffDate>localDate()){showToast("Comp-off usage cannot be recorded for a future date");return}const earned=compOffAvailableEntries(compOffDate)[0];if(!earned){showToast("No earned comp-off is available on the selected date");return}setCompOffEntries(old=>normalizeCompOffEntries([...old,{id:crypto.randomUUID(),type:"used",date:compOffDate,earnedEntryId:earned.id,notes:compOffNote.trim()||"Comp-off taken"}]));setCompOffNote("");showToast("Comp-off usage linked to earned date "+earned.date);}
 function editCompOffEntry(entry:CompOffEntry){const date=window.prompt("Entry date (YYYY-MM-DD)",entry.date);if(date===null)return;if(!isValidISODate(date)){showToast("Enter a valid date");return}if(date>localDate()){showToast("Comp-off ledger entries cannot be moved to a future date");return}if(entry.type==="earned"){const kind=compOffDayType(date);if(!kind){showToast("The edited earning date must be a qualifying non-working day");return}if(kind.startsWith("Reference holiday")&&!window.confirm("This is a central, restricted or provisional reference. Confirm your office was closed on this date?"))return}const notes=window.prompt("Notes",entry.notes||"");if(notes===null)return;const normalized=normalizeCompOffEntries(compOffEntries);if(entry.type==="earned"&&hasLinkedCompOffUsage(normalized,entry.id)){showToast("This earned day has linked usage. Delete the usage first before changing its earning date.");return}if(entry.type==="used"&&!isValidCompOffUsageDate(normalized,entry.id,date)){showToast("Usage date must fall between the linked earned date and its three-month expiry.");return}if(entry.type==="earned"&&normalized.some(e=>e.id!==entry.id&&e.type==="earned"&&e.date===date)){showToast("An earned entry already exists for this date");return}setCompOffEntries(old=>normalizeCompOffEntries(old.map(e=>e.id===entry.id?{...e,date,notes,...(e.type==="earned"?{expiresAt:compOffExpiry(date)}:{})}:e)));}
 function deleteCompOffEntry(entry:CompOffEntry){const normalized=normalizeCompOffEntries(compOffEntries);if(entry.type==="earned"&&hasLinkedCompOffUsage(normalized,entry.id)){showToast("This earned day has already been used. Delete the linked usage entry first.");return}if(!window.confirm(entry.type==="used"?"Delete this comp-off usage? Its linked earned day will be available again only if it has not expired.":"Delete this earned comp-off entry?"))return;setCompOffEntries(old=>normalizeCompOffEntries(old.filter(e=>e.id!==entry.id)));showToast(entry.type==="used"?"Usage deleted; linked balance recalculated":"Earned comp-off entry deleted");}
 function exportCompOffExcel(){const rows=[["Type","Date","Notes"],...compOffEntries.filter(e=>e.date>=compOffFrom&&e.date<=compOffTo).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>[e.type==="earned"?"Earned":"Used",e.date,e.notes||""])];const csv="\uFEFF"+rows.map(row=>row.map(v=>'"'+String(v??"").replaceAll('"','""')+'"').join(",")).join("\n");const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download="officeflow-comp-off-"+compOffFrom+"-to-"+compOffTo+".csv";a.click();URL.revokeObjectURL(url);}
 function saveMeeting(){const m=meetingDraft;if(!m.subject.trim()||!m.date||!m.start||!m.client.trim()||!Number.isFinite(m.duration)||m.duration<=0||m.duration>1440){showToast("Complete the meeting details and enter a valid duration");return}const dates=meetingOccurrenceDates(m.date,m.recurrence as any,12);if(!dates.length){showToast("Enter a valid meeting date");return}if(hasMeetingConflict(meetings,m)){showToast("This meeting or one of its recurring dates overlaps an existing meeting. Choose another slot.");return}const seriesId=m.recurrence!=="None"?crypto.randomUUID():undefined;const occurrences=dates.map((date,index)=>({...m,id:crypto.randomUUID(),date,...(seriesId?{seriesId,occurrenceIndex:index+1}:{})}));setMeetings(old=>[...old,...occurrences]);setMeetingDraft(old=>({...old,client:"",contact:"",subject:"",notes:"",date:localDate(),start:"10:00"}));showToast(seriesId?occurrences.length+" recurring meetings scheduled":"Meeting scheduled");}
 function addCompOffHoliday(){if(!isValidISODate(holidayDate)||!holidayName.trim()){showToast("Enter a holiday name and date");return}setCompOffHolidays(old=>{const existing=old.find(h=>h.date===holidayDate);const next=existing?old.map(h=>h.date===holidayDate?{...h,name:holidayName.trim()}:h):[...old,{date:holidayDate,name:holidayName.trim(),status:"office-confirmed" as const,sourceLabel:"Added by the workspace manager as an office holiday"}];return next.sort((a,b)=>a.date.localeCompare(b.date))});setHolidayName("");showToast("Holiday saved; reference status retained where applicable");}
