 function exportDiaryReport(){const [from,to]=diaryRange();const rows=[["Date","Client","Task / matter","Entry","Person"],...tasks.flatMap(t=>(t.activity||[]).filter(e=>indiaDateFromTimestamp(e.at)>=from&&indiaDateFromTimestamp(e.at)<=to&&(e.message.startsWith("Work performed")||e.message.startsWith("Checklist completed:"))&&(diaryReportMember==="All"||e.actor===diaryReportMember)).map(e=>[indiaDateFromTimestamp(e.at),t.client,t.title,e.message,e.actor||""]))];const csv="\uFEFF"+rows.map(row=>row.map(v=>'"'+String(v??"").replaceAll('"','""')+'"').join(",")).join("\n");const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download="officeflow-diary-"+diaryPeriod+"-"+from+"-to-"+to+".csv";a.click();URL.revokeObjectURL(url);}
 function addDiaryEntry(){const task=tasks.find(t=>t.id===diaryTaskId);if(!diaryClient||!task||task.client!==diaryClient){showToast("Choose a task belonging to the selected client");return}if(!diaryText.trim()){showToast("Describe the work completed");return}const now=new Date();const clock=indiaClockTime(now);const at=indiaLocalDateTimeToISO(diaryDate,clock);if(!at){showToast("Select a valid diary date");return}const duration=diaryDuration.trim();if(duration&&!/^(?:\d+(?:\.\d+)?\s*(?:m|min|mins|minutes?|h|hr|hrs|hours?)(?:\s+\d+\s*(?:m|min|mins|minutes?))?|\d{1,2}:\d{2})$/i.test(duration)){showToast("Enter time as minutes, hours, or HH:MM");return}const entry={at,actor:currentDisplayName,message:"Work performed"+(duration?" · "+duration:"")+" — "+diaryText.trim()};setTasks(old=>old.map(t=>t.id===task.id?{...t,activity:[...(t.activity||[]),entry]}:t));setDiaryText("");setDiaryDuration("");showToast("Work recorded against "+task.client)}
 function exportMyWorkPNG(){const canvas=document.createElement("canvas");const ctx=canvas.getContext("2d");if(!ctx)return;const entries=tasks.flatMap(t=>(t.activity||[]).filter(e=>indiaDateFromTimestamp(e.at)===diaryDate&&(e.message.startsWith("Work performed")||e.message.startsWith("Checklist completed:"))).map(e=>t.client+" | "+t.title+" | "+e.message));const lines=["MY WORK REPORT - "+diaryDate,"",...entries];ctx.font="22px Arial";const wrapped:string[]=[];for(const line of lines){if(!line){wrapped.push("");continue}let cur="";for(const word of line.split(" ")){const test=cur?cur+" "+word:word;if(ctx.measureText(test).width>940&&cur){wrapped.push(cur);cur=word}else cur=test}wrapped.push(cur)}canvas.width=1020;canvas.height=Math.max(360,140+wrapped.length*36);ctx.fillStyle="#eaf7f1";ctx.fillRect(0,0,1020,canvas.height);ctx.fillStyle="#063a34";ctx.fillRect(0,0,1020,85);ctx.fillStyle="#fff";ctx.font="bold 30px Arial";ctx.fillText("OFFICEFLOW / MY WORK",40,55);wrapped.forEach((v,i)=>{ctx.fillStyle=i===0?"#087c67":"#173e35";ctx.font=i===0?"bold 24px Arial":"22px Arial";ctx.fillText(v,40,135+i*36)});const a=document.createElement("a");a.download="officeflow-work-"+diaryDate+".png";a.href=canvas.toDataURL("image/png");a.click();showToast("PNG exported")}
