async function registerWorkspaceMember(e:React.FormEvent){
 e.preventDefault();
 if(!supabase||!session?.user||workspaceRole!=="manager"){setMemberMessage("Only a signed-in manager can add workspace members.");return}
 if(!newMember.email.trim()||!newMember.display_name.trim()){setMemberMessage("Enter the member email and display name. To add a person without an account, choose Add work member only.");return}
 setMemberBusy(true);setMemberMessage("");
 try{
  const {error}=await supabase.rpc("officeflow_register_member",{p_email:newMember.email.trim(),p_role:newMember.role,p_display_name:newMember.display_name.trim(),p_phone_number:newMember.phone_number.trim()});
  if(error)throw error;
  const {data:workspaceData,error:workspaceError}=await supabase.rpc("officeflow_get_workspace");
  if(workspaceError)throw workspaceError;
  setWorkspaceMembers(Array.isArray((workspaceData as any)?.members)?(workspaceData as any).members:[]);
  if(newMember.role==="junior")upsertJuniorDirectoryEntry(newMember.display_name,newMember.phone_number,newMember.email);
  setMemberMessage("Workspace access granted. The user should sign in again to load their role.");
  setNewMember({email:"",display_name:"",phone_number:"",role:"junior"});
 }catch(err){const detail=typeof err==="object"&&err!==null&&"message" in err&&typeof (err as any).message==="string"?(err as any).message:"Could not add workspace member.";if(newMember.role==="junior"&&newMember.display_name.trim()){upsertJuniorDirectoryEntry(newMember.display_name,newMember.phone_number,newMember.email);setMemberMessage(`Sign-in access was not granted. ${detail} Added ${newMember.display_name.trim()} as a work member for task assignment. Once they have an OfficeFlow account, choose Grant sign-in access beside their name.`);}else setMemberMessage(detail);}
 finally{setMemberBusy(false)}
}
function addWorkMemberFromAccessForm(){if(workspaceRole!=="manager"){setMemberMessage("Manager access is required to add work members.");return}if(!newMember.display_name.trim()){setMemberMessage("Enter a display name to add this work member.");return}upsertJuniorDirectoryEntry(newMember.display_name,newMember.phone_number,newMember.email);setMemberMessage(`${newMember.display_name.trim()} is now available for task assignment. Sign-in access is separate.`);showToast("Work member added")}
